// eslint-disable-next-line @typescript-eslint/no-magic-numbers
const JAVA_MAX_INT = 2 ** 31 - 1

function NumericInput(props: React.JSX.IntrinsicElements['input']) {
  return <input type="number" min={1} max={JAVA_MAX_INT} className={styles.input} {...props} />
}

type ActionsSectionProps = {
  actionPerforming?: boolean
  onCancelClick?: (event: React.MouseEvent<HTMLButtonElement>) => void
}
function ActionsSection({actionPerforming, onCancelClick}: ActionsSectionProps) {
  const error = useAppSelector(getCustomError)
  return (
    <Panel className={styles.panel}>
      <Button primary type="submit" loader={actionPerforming}>
        {'Update'}
      </Button>
      <Button onClick={onCancelClick} loader={actionPerforming}>
        {'Cancel'}
      </Button>
      {error != null && (
        <div className={styles.error}>
          <div key={error.errorId}>{error.message}</div>
        </div>
      )}
    </Panel>
  )
}

