function EditForm({
  policyEntry,
  type,
  onCancelClick,
  onCompleteClick = noop,
  formVisible,
  actionPerforming,
}: OwnProps) {
  const [state, dispatch] = React.useReducer(reducer, getInitialState(policyEntry))
  const setRadioVisible = React.useCallback(
    (value: string) => {
      const [entity, _, val] = value.split('.')
      dispatch({
        value: val,
        entity: entity as Entity,
        type: actions.SET_CUSTOM,
      })
    },
    [dispatch],
  )
  const setDependencies = React.useCallback(
    (value: EditFormState['dependencies']) =>
      dispatch({
        type: actions.SET_DEPENDENCIES,
        value,
      }),
    [dispatch],
  )
  const inputChangeHandler = React.useCallback(
    (event: React.ChangeEvent<HTMLInputElement>) => {
      if (!event.target.checkValidity()) {
        return
      }

      let value: number | null = parseInt(event.target.value.replace(/([^0-9])/g, ''), 10)

      if (isNaN(value)) {
        value = null
      }

      const id = event.target.id
      const [entity, _, kind] = id.split('.')
      dispatch({
        type: actions.SET_VALUE,
        entity: entity as Entity,
        kind: kind as keyof FormGroup,
        value,
      })
    },
    [dispatch],
  )
  const onArtifactsPatternChange = React.useCallback(
    (value: string) => {
      dispatch({
        type: actions.SET_ARTIFACTS_VALUE,
        value,
      })
    },
    [dispatch],
  )
  const validateForm = React.useCallback(() => {
    const {artifacts, everything, history} = state
    let valid = true

    const reportErrorIfExists = (entity: Entity, error: string | null) => {
      if (error == null) {
        return
      }

      valid = false
      dispatch({
        type: actions.SET_ERROR,
        entity,
        error,
      })
    }

    reportErrorIfExists('artifacts', VALIDATIONS.not_specified(artifacts))
    reportErrorIfExists('history', VALIDATIONS.not_specified(history))
    reportErrorIfExists('everything', VALIDATIONS.not_specified(everything))
    return valid
  }, [state])

  const onSubmit = (event: React.FormEvent<HTMLFormElement>) => {
    event.preventDefault()
    const valid = validateForm()

    if (!valid) {
      return
    }

    const {artifacts, everything, history, dependencies} = state
    const result: UpdatePolicyPayload = adaptFormToPolicy({
      artifacts,
      everything,
      history,
      dependencies,
      policyEntry,
      type,
    })
    onCompleteClick(result)
  }

  const policyName = policyEntry?.name ? policyEntry.name.split(' / ').pop() : ''
  const title = `Base\u00a0rule for\u00a0${policyName}\u2060`
  return (
    <Dialog
      label={title}
      contentClassName={styles.editForm}
      show={formVisible}
      onEscPress={onCancelClick}
      onCloseClick={onCancelClick}
      trapFocus
      autoFocusFirst={false}
      showCloseButton
      closeButtonInside
    >
      <Header>{title}</Header>
      <div className={classNames(styles.description, styles.headerHint)}>
        {`
          Base\u00a0rule allows for\u00a0preserving build\u00a0data using simple settings. The\u00a0rule is\u00a0applied considering branches, personal and canceled\u00a0builds,\u00a0etc.
        `}
        <HelpLink
          url={resolveHelpURL('clean-up.html#Clean-up-BaseRule')}
          Component={IconButton}
          icon="help"
        />
      </div>
      <Form onSubmit={onSubmit} className={styles.form}>
        <Content>
          <div>
            <ArtifactsSection
              data={state.artifacts}
              onArtifactsPatternChange={onArtifactsPatternChange}
              inputChangeHandler={inputChangeHandler}
              setRadioVisible={setRadioVisible}
              policyEntry={policyEntry}
              type={type}
            />
            <HistorySection
              data={state.history}
              inputChangeHandler={inputChangeHandler}
              setRadioVisible={setRadioVisible}
            />
            <EverythingSection
              data={state.everything}
              inputChangeHandler={inputChangeHandler}
              setRadioVisible={setRadioVisible}
            />
            <ArtifactsDependenciesSection
              dependencies={state.dependencies}
              setDependencies={setDependencies}
              isRoot={policyEntry.externalId === ROOT_PROJECT_ID}
            />
          </div>
        </Content>
        <ActionsSection actionPerforming={actionPerforming} onCancelClick={onCancelClick} />
      </Form>
    </Dialog>
  )
}

export default EditForm
